const items = $input.all();
const cleanedRecords = [];

// Helper to safely parse raw or escaped AI string responses
function parseAiOutput(raw) {
  if (!raw) return null;
  if (typeof raw === 'object') return raw;

  if (typeof raw === 'string') {
    // 1. Strip markdown fences, backticks, and whitespace
    let cleaned = raw
      .replace(/```(?:json)?/gi, '')
      .replace(/```/g, '')
      .replace(/\u00a0/g, ' ')
      .trim();

    // 2. Unescape wrapping outer quotes if double-stringified
    if (cleaned.startsWith('"') && cleaned.endsWith('"')) {
      try {
        cleaned = JSON.parse(cleaned);
      } catch (e) {
        // Continue if single parse fails
      }
    }

    // 3. Extract JSON object boundaries { ... } or array [ ... ]
    const firstBrace = cleaned.search(/[\{\[]/);
    const lastBrace = Math.max(cleaned.lastIndexOf('}'), cleaned.lastIndexOf(']'));

    if (firstBrace !== -1 && lastBrace !== -1) {
      cleaned = cleaned.substring(firstBrace, lastBrace + 1);
    }

    try {
      return JSON.parse(cleaned);
    } catch (err) {
      // Fallback for unescaped control chars / stray line returns
      const sanitized = cleaned.replace(/[\n\r\t]/g, ' ');
      return JSON.parse(sanitized);
    }
  }

  return null;
}

for (const item of items) {
  // Extract output from common AI node keys: text, output, message.content, or root
  const rawTarget = item.json?.text ?? item.json?.output ?? item.json?.message?.content ?? item.json;

  let parsed;
  try {
    parsed = parseAiOutput(rawTarget);
  } catch (err) {
    continue; // Skip malformed non-JSON items
  }

  if (!parsed) continue;

  // Normalize single object vs array of objects
  const records = Array.isArray(parsed) ? parsed : [parsed];

  for (const rec of records) {
    if (!rec || typeof rec !== 'object') continue;

    cleanedRecords.push({
      json: {
        name: rec.name?.trim() ?? '',
        first_name: rec.first_name?.trim() ?? '',
        last_name: rec.last_name?.trim() ?? '',
        email: rec.email?.trim()?.toLowerCase() ?? '',
        department: rec.department?.trim() ?? '',
        role: rec.role?.trim() ?? '',
        office: rec.office?.trim() ?? '',
        salary: Number(rec.salary) || 0,
        start_date: rec.start_date ?? '',
        years_of_experience: Number(rec.years_of_experience) || 0,
        region: rec.region?.trim() ?? '',
        // Include any remaining custom fields dynamically
        ...rec
      }
    });
  }
}

return cleanedRecords;
